  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["U1", "U2"],
      "pins": ["U1.1", "U2.1", "U1.2", "U2.2", "U1.3", "U2.3", "U1.5", "U2.5", "U1.6", "U2.6", "U1.7", "U2.7"],
      "nets": ["NET0005", "NET0009", "NET0010", "NET0002", "NET0006", "NET0003"],
      "observed": "The ATtiny45 U1 and ATtiny13V U2 have their reset and GPIO pins connected in parallel: reset on NET0005, PB3 on NET0009, PB4 on NET0010, PB0 on NET0002, PB1 on NET0006, and PB2 on NET0003. Both also share the ISP connector signals.",
      "expected": "A fan controller should use one active MCU, or explicitly make the two MCU placements mutually exclusive. If both are fitted, the shared GPIOs and reset/ISP lines can cause output contention and prevent independent operation.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"8\") (name \"NET0005\") ... (node (ref \"U1\") (pin \"1\") ...) (node (ref \"U2\") (pin \"1\") ...))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"6\") (name \"NET0002\") ... (node (ref \"U1\") (pin \"5\") ...) (node (ref \"U2\") (pin \"5\") ...))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"9\") (name \"NET0006\") ... (node (ref \"U1\") (pin \"6\") ...) (node (ref \"U2\") (pin \"6\") ...))"
        },
        {
          "source": "spec",
          "quote": "an ATtiny-driven fan controller"
        }
      ],
      "impact": "If both MCU footprints are populated, their GPIO outputs can fight each other and the shared ISP connection cannot select them independently. The board only behaves safely as a single-MCU design if one MCU is intentionally left unpopulated.",
      "confidence": 0.79
    }
  ],
  "summary": "The netlist connects two different ATtiny devices in parallel across their reset, GPIO, and ISP signals. This is hazardous if both are fitted; the files do not indicate that the MCU placements are mutually exclusive."
}

